namespace {const QString Id="12345678-1234-1234-1234-123456789abc";unsigned checks{};}
void check(bool b,const char* what){if(!b)throw std::runtime_error(what);++checks;}
QByteArray read(const std::filesystem::path& path){QFile f(QString::fromStdString(path.string()));check(f.open(QIODevice::ReadOnly),"fixture read");return f.readAll();}
QString hash(const QByteArray& bytes){return QString::fromLatin1(QCryptographicHash::hash(bytes,QCryptographicHash::Sha256).toHex());}
void write(const std::filesystem::path& path,const QByteArray& bytes){QFile f(QString::fromStdString(path.string()));check(f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size(),"fixture write");}
bool glyphPainted(const epub::PageRaster& raster,QJsonArray quad){double x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;auto m=raster.forward;for(int i=0;i<8;i+=2){double x=quad[i].toDouble(),y=quad[i+1].toDouble(),sx=m[0].toDouble()*x+m[2].toDouble()*y+m[4].toDouble(),sy=m[1].toDouble()*x+m[3].toDouble()*y+m[5].toDouble();x0=std::min(x0,sx);x1=std::max(x1,sx);y0=std::min(y0,sy);y1=std::max(y1,sy);}for(int y=std::max(0,int(std::floor(y0)));y<std::min(raster.height,int(std::ceil(y1)));++y)for(int x=std::max(0,int(std::floor(x0)));x<std::min(raster.width,int(std::ceil(x1)));++x){auto p=raster.rgb32[y*raster.stride+x];if(((p>>16)&255)<180&&((p>>8)&255)<180&&(p&255)<180)return true;}return false;}
void verify(const epub::PageRaster& r){check(r.width==1620&&r.height==2060&&r.stride==1620&&r.rgb32.size()==1620u*2060,"bounded raster dimensions");for(auto pixel:r.rgb32)check(pixel>>24==255,"opaque RGB32");check(r.bounds.size()==4&&r.forward.size()==6&&r.inverse.size()==6,"raster transform shape");for(auto point:{std::pair{0.,0.},std::pair{123.4,79.2}}){auto m=r.forward,n=r.inverse;double x=m[0].toDouble()*point.first+m[2].toDouble()*point.second+m[4].toDouble(),y=m[1].toDouble()*point.first+m[3].toDouble()*point.second+m[5].toDouble();check(std::abs(n[0].toDouble()*x+n[2].toDouble()*y+n[4].toDouble()-point.first)<1e-8&&std::abs(n[1].toDouble()*x+n[3].toDouble()*y+n[5].toDouble()-point.second)<1e-8,"exact fit inverse");}}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 if(argc==6&&std::string_view(argv[1])=="--resolve"){epub::ReflowDocument doc(argv[2],Id,QString::fromUtf8(argv[3]),{200,160,24});auto anchor=QJsonDocument::fromJson(read(argv[4])).object();auto result=doc.resolve(anchor);check(result["status"]=="resolved","fresh reflow anchor resolve");unsigned fragments=0;for(auto value:result["fragments"].toArray()){auto f=value.toObject();int number=f["page"].toInt();auto geometry=doc.page(number);auto raster=doc.renderPage(number);verify(raster);check(geometry["layoutId"]==doc.layoutId()&&geometry["sourceSha256"]==doc.sourceSha256(),"render/text share layout identity");bool painted=false;for(auto q:f["quads"].toArray())painted|=glyphPainted(raster,q.toArray());check(painted,"resolved source quads meet actual rendered glyphs");++fragments;}write(argv[5],QJsonDocument(QJsonObject{{"pages",doc.pageCount()},{"fragments",int(fragments)},{"layoutId",doc.layoutId()}}).toJson());return 0;}
 check(argc==3,"usage root sysroot");std::filesystem::path root=argv[1],sys=argv[2],fixture=root/"fixtures/library/authored-three-chapters.epub";auto original=read(fixture);auto sha=hash(original);QTemporaryDir tmp;check(tmp.isValid(),"temporary root");std::filesystem::path scratch=tmp.path().toStdString();auto copied=scratch/"immutable.epub";write(copied,original);epub::ReflowDocument doc(copied,Id,sha);check(doc.layoutId()=="epub-reflow-v1:"+hash(QJsonDocument(doc.layoutDescriptor()).toJson(QJsonDocument::Compact)),"canonical descriptor is layout hash input");check(doc.layoutDescriptor()["publisherCss"]==true&&doc.layoutDescriptor()["userCss"]=="","actual existing CSS descriptor retained");
 for(int number=0;number<3;++number){auto geometry=doc.page(number);auto raster=doc.renderPage(number);verify(raster);check(raster.bounds==QJsonArray{0,0,600,800},"actual laid out page bounds");unsigned colored=0;for(auto pixel:raster.rgb32){unsigned red=(pixel>>16)&255,green=(pixel>>8)&255,blue=pixel&255;if(number==0?red>220&&green<70&&blue<70:number==1?green>220&&red<70&&blue<70:blue>220&&red<70&&green<70)++colored;}check(colored>1000,"embedded chapter image rendered");auto first=geometry["chars"].toArray().first().toObject()["quad"].toArray();check(glyphPainted(raster,first),"text geometry maps to actual glyph pixels");}
 auto geometry=doc.page(1);auto text=geometry["text"].toString();int first=text.indexOf("The river"),last=text.indexOf("page.",first)+5;check(first>=0&&last>first,"selection fixture");auto captured=doc.captureSelection(1,first,last,text.mid(first,last-first));check(captured["status"]=="anchored","anchor capture");write(scratch/"anchor.json",QJsonDocument(captured["anchor"].toObject()).toJson());QProcess child;child.setProgram(QString::fromStdString((sys/"usr/lib/ld-linux-aarch64.so.1").string()));child.setArguments({"--library-path",QString::fromStdString((sys/"usr/lib").string()),QString::fromUtf8(argv[0]),"--resolve",QString::fromStdString(fixture.string()),sha,QString::fromStdString((scratch/"anchor.json").string()),QString::fromStdString((scratch/"resolved.json").string())});child.start();bool done=child.waitForStarted(5000)&&child.waitForFinished(60000);if(!done||child.exitCode())std::cerr<<child.readAllStandardError().constData();check(done&&child.exitStatus()==QProcess::NormalExit&&child.exitCode()==0,"fresh process render/anchor proof");auto resolved=QJsonDocument::fromJson(read(scratch/"resolved.json")).object();check(resolved["pages"].toInt()>doc.pageCount()&&resolved["layoutId"]!=doc.layoutId()&&resolved["fragments"].toInt()>1,"changed typography reflows pages and renders resolved fragments");
 auto before=doc.renderPage(1);write(copied,"not an EPUB");check(doc.renderPage(1).rgb32==before.rgb32&&doc.page(1)==geometry,"render and geometry use same immutable source snapshot");for(int bad:{-1,doc.pageCount()}){bool rejected=false;try{doc.renderPage(bad);}catch(const std::runtime_error& e){rejected=std::string(e.what())=="epub-reflow-page-index";}check(rejected,"invalid page rejected before rendering");}bool rejected=false;try{epub::ReflowDocument bad(copied,Id,sha);}catch(const std::runtime_error& e){rejected=std::string(e.what())=="epub-reflow-source-sha-mismatch";}check(rejected,"invalid source rejected before parsing");rejected=false;try{epub::ReflowDocument tiny(fixture,Id,sha,{100,100,6});tiny.renderPage(0);}catch(const std::runtime_error& e){rejected=std::string(e.what())=="epub-raster-fit-scale";}check(rejected,"ink incompatible scale rejected");check(hash(read(fixture))==sha,"fixture unchanged");std::cout<<"EPUB_RASTER_PASS fresh_process=true physical=NOT_RUN\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
